-- Script 125 · parte 3 de 6: depósitos de la organización 3 y su detalle contable (717 depósitos y 28 líneas).
--   Ejecutar las 6 partes en orden en el SQL Editor de Supabase. Es el mismo script 125 partido: el resultado es
--   igual a ejecutarlo completo, y cada parte se puede ejecutar de nuevo (solo actualiza).
alter table public.movimientos_bancarios add column if not exists deposito_anterior integer;
alter table public.movimientos_bancarios add column if not exists banco_anterior integer;
alter table public.movimientos_bancarios add column if not exists estatus_anterior text;
alter table public.movimientos_bancarios add column if not exists origen_anterior text;
alter table public.movimientos_bancarios add column if not exists conciliado_anterior text;
alter table public.movimientos_bancarios add column if not exists moneda_integracion integer;
alter table public.movimientos_bancarios add column if not exists valor_cambio_anterior numeric(18, 6);
alter table public.movimientos_bancarios add column if not exists transaccion_anterior integer;
alter table public.movimientos_bancarios add column if not exists valor_mi numeric(18, 2);
alter table public.movimientos_bancarios add column if not exists valor_anterior numeric(18, 2);
alter table public.movimientos_bancarios add column if not exists cuenta_bancaria_anterior text;
alter table public.movimientos_bancarios add column if not exists cliente_codigo_anterior integer;
alter table public.movimientos_bancarios add column if not exists recibo_anterior text;
alter table public.movimientos_bancarios add column if not exists fecha_anterior timestamp;
alter table public.movimientos_bancarios add column if not exists usuario_modifica_anterior text;
alter table public.movimientos_bancarios add column if not exists fecha_modifica_anterior date;
alter table public.movimiento_lineas add column if not exists debe_mi numeric(18, 2);
alter table public.movimiento_lineas add column if not exists haber_mi numeric(18, 2);
alter table public.movimiento_lineas add column if not exists cuenta_codigo_anterior text;
alter table public.movimiento_lineas add column if not exists version_cuenta_anterior integer;
alter table public.movimiento_lineas add column if not exists centro_costo_anterior text;
alter table public.movimiento_lineas add column if not exists usuario_ingresa_anterior text;
alter table public.movimiento_lineas add column if not exists fecha_ingresa_anterior timestamp;
alter table public.movimiento_lineas add column if not exists usuario_modifica_anterior text;
alter table public.movimiento_lineas add column if not exists fecha_modifica_anterior timestamp;
create index if not exists movimientos_bancarios_deposito_anterior on public.movimientos_bancarios (localidad_id, tipo, deposito_anterior) where deposito_anterior is not null;
-- La cuenta 1010201005 (clientes, usada en 1,160 depósitos de la 3-01 de 2017 a 2022) no está en el catálogo: se crea en la
-- versión 1 de la 3-01, bajo 1010201 CLIENTES, como no vigente (no se ofrece para datos nuevos). Puede cambiarle el nombre.
insert into public.cuentas (catalogo_id, codigo, nombre, cuenta_mayor_id, tipo_cuenta_id, integra, vigente, cuenta_anterior)
select p.catalogo_id, '1010201005', 'CLIENTES (CUENTA DEL SISTEMA ANTERIOR)', p.id, p.tipo_cuenta_id, p.integra, false, '1010201005'
from public.cuentas p join public.catalogos_cuentas g on g.id = p.catalogo_id join public.localidades l on l.id = g.localidad_id join public.organizaciones o on o.id = l.organizacion_id
where o.codigo = '3' and l.correlativo = 1 and g.version = 1 and p.codigo = '1010201'
  and not exists (select 1 from public.cuentas x where x.catalogo_id = p.catalogo_id and x.codigo = '1010201005');

do $migra$
declare
  v_org bigint; v_gtq bigint; v_usd bigint;
  r record; v_loc bigint; v_cb record; v_id bigint; v_folio integer; v_nom text; v_tr_id bigint; v_tr_op text; v_cta bigint; v_nuevo boolean;
  v_usdcta boolean; v_valor numeric; v_cambio numeric; v_faltan text[] := '{}';
  c_n int := 0; c_a int := 0; c_s int := 0; l_n int := 0; l_a int := 0; l_s int := 0; l_c int := 0; d_n int := 0;
begin
  select id into v_org from public.organizaciones where codigo = '3';
  if v_org is null then raise notice 'No existe la organización 3.'; return; end if;
  select id into v_gtq from public.monedas where iso = 'GTQ';
  select id into v_usd from public.monedas where iso = 'USD';
