    (2, '206-131947-7', 584, '4536519', '2023-08-11', 18995, null, 7.7, 1, 'FE-1142', 'OLM', '2023-08-20 15:54:46', 'I', null, null, false, 40, '1171', false, null, null, null, 20, 'A', '2023-08-11 00:00:00'),
    (2, '206-131947-7', 595, '28884034', '2023-08-14', 800, null, 7.7, 1, 'FE-1184', 'OLM', '2023-09-08 16:43:13', 'I', null, null, false, 49, '1185', false, null, null, null, 20, 'A', '2023-08-14 00:00:00'),
    (2, '206-131947-7', 596, '28884033', '2023-08-14', 2400, null, 7.7, 1, 'FE-1182', 'OLM', '2023-09-08 16:44:11', 'I', null, null, false, 49, '1186', false, null, null, null, 20, 'A', '2023-08-14 00:00:00')) as x(loc, cuenta, documento, numero, fecha, monto, monto_mi, cambio, moneda_int, descripcion, emisor, f_ingreso, conciliado, f_concilia,
      transaccion, varios, cliente, recibo, caja_chica, depositante, usr_mod, f_mod, banco, estatus, fecha_ant)
    order by loc, fecha, documento loop
    select id into v_loc from public.localidades where organizacion_id = v_org and correlativo = r.loc;
    v_cb := null;
    select cb.id, cb.moneda_id into v_cb from public.cuentas_bancarias cb where cb.localidad_id = v_loc and cb.numero = r.cuenta::text;
    if v_cb.id is null then c_s := c_s + 1; raise notice 'Depósito % (3-0%): no tiene cuenta bancaria o no existe (%).', r.documento, r.loc, coalesce(r.cuenta::text, 'sin cuenta'); continue; end if;
    -- En las cuentas de dólares el MONTO viene en quetzales: el valor en US$ es MONTO_MI o MONTO / VALOR_CAMBIO.
    v_usdcta := v_cb.moneda_id = v_usd;
    v_cambio := case when v_usdcta and coalesce(r.cambio::numeric, 0) > 0 then r.cambio::numeric else 1 end;
    v_valor := case when v_usdcta then coalesce(r.monto_mi::numeric, round(r.monto::numeric / v_cambio, 2)) else r.monto::numeric end;
    v_id := null;
    select id into v_id from public.movimientos_bancarios where localidad_id = v_loc and tipo = 'DEPOSITO' and deposito_anterior = r.documento;
    v_nom := case when r.cliente is not null then (select coalesce(nombre, razon_social) from public.clientes where localidad_id = v_loc and codigo::text = r.cliente::text limit 1) end;
    v_tr_id := null; v_tr_op := null;
    select id, tipo_operacion into v_tr_id, v_tr_op from public.transacciones_contables where localidad_id = v_loc and numero = r.transaccion::integer and r.transaccion::integer <> 0;
    if v_id is null then
      select coalesce(max(folio), 0) + 1 into v_folio from public.movimientos_bancarios where localidad_id = v_loc and tipo = 'DEPOSITO';
      insert into public.movimientos_bancarios (organizacion_id, localidad_id, cuenta_bancaria_id, tipo, folio, numero_documento, fecha, moneda_id, tipo_cambio,
        valor, valor_ml, valor_cuenta, estado, usuario, fecha_operacion, deposito_anterior, origen_anterior)
      values (v_org, v_loc, v_cb.id, 'DEPOSITO', v_folio, coalesce(r.numero::text, r.documento::text), r.fecha::date, v_gtq, 1, v_valor, v_valor, v_valor, 'ACTIVO',
        coalesce(upper(r.emisor::text), 'SISTEMA ANTERIOR'), coalesce(r.f_ingreso::timestamp, r.fecha::timestamp)::timestamptz, r.documento, 'MIGRADO')
      returning id into v_id;
      c_n := c_n + 1;
    else
      c_a := c_a + 1;
    end if;
    update public.movimientos_bancarios set cuenta_bancaria_id = v_cb.id, numero_documento = coalesce(r.numero::text, r.documento::text), fecha = r.fecha::date,
      moneda_id = case when v_usdcta then v_usd else v_gtq end, tipo_cambio = v_cambio, valor = v_valor, valor_ml = round(v_valor * v_cambio, 2), valor_cuenta = v_valor,
      descripcion = nullif(trim(r.descripcion::text), ''), deposito_por = nullif(trim(r.depositante::text), ''),
      tipo_tercero = case when coalesce(r.varios::boolean, false) then 'CLIENTES VARIOS' else 'CLIENTE' end,
      tercero_codigo = r.cliente::text, tercero_nombre = v_nom,
      transaccion_id = coalesce(v_tr_id, transaccion_id), tipo_operacion = coalesce(v_tr_op, tipo_operacion),
      conciliado = upper(coalesce(r.conciliado::text, '')) = 'C', fecha_conciliado = r.f_concilia::date,
      caja_chica = coalesce(r.caja_chica::boolean, false), clientes_varios = coalesce(r.varios::boolean, false),
      usuario = coalesce(upper(r.emisor::text), usuario), fecha_operacion = coalesce(r.f_ingreso::timestamp::timestamptz, fecha_operacion),
      origen_anterior = 'MIGRADO', deposito_anterior = r.documento, banco_anterior = r.banco::integer, estatus_anterior = r.estatus::text,
      conciliado_anterior = r.conciliado::text, moneda_integracion = r.moneda_int::integer, valor_cambio_anterior = r.cambio::numeric,
      transaccion_anterior = r.transaccion::integer, valor_mi = r.monto_mi::numeric, valor_anterior = r.monto::numeric, cuenta_bancaria_anterior = r.cuenta::text,
      cliente_codigo_anterior = r.cliente::integer, recibo_anterior = r.recibo::text, fecha_anterior = r.fecha_ant::timestamp,
      usuario_modifica_anterior = r.usr_mod::text, fecha_modifica_anterior = r.f_mod::date
    where id = v_id;
    -- Recibo físico del cliente (pestaña «Recibos físicos»): uno por depósito, por su valor.
    if r.recibo is not null then
      delete from public.movimiento_documentos where movimiento_id = v_id and tipo = 'RECIBO';
      insert into public.movimiento_documentos (movimiento_id, tipo, numero, tercero, nombre, valor, valor_ml, fecha, estado)
      values (v_id, 'RECIBO', r.recibo::text, r.cliente::text, v_nom, v_valor, round(v_valor * v_cambio, 2), r.fecha::date, 'EMITIDO');
      d_n := d_n + 1;
    end if;
  end loop;

  -- Detalle contable: cuentas del catálogo de la versión indicada (1) de la localidad.
  for r in select * from (values
    (1, 1506, 1, '1010102002', 1, 750, 0, null, null, '0', 'FRA', '2023-11-10 07:41:11', null, null),
    (1, 1506, 2, '1010201001', 1, 0, 750, null, null, '0', 'FRA', '2023-11-10 07:41:11', null, null),
    (1, 1510, 1, '1010102002', 1, 12000, 0, null, null, '0', 'FRA', '2023-11-10 07:41:01', null, null),
    (1, 1510, 2, '1010201001', 1, 0, 12000, null, null, '0', 'FRA', '2023-11-10 07:41:01', null, null),
    (1, 1613, 1, '1010102002', 1, 12600, 0, 1636.36, null, '0', 'LMI', '2025-01-15 11:01:01', null, null),
    (1, 1613, 2, '1010201001', 1, 0, 12600, null, 1636.36, '0', 'LMI', '2025-01-15 11:01:01', null, null),
    (1, 1651, 1, '1010102001', 1, 1000, 0, null, null, '0', 'OLM', '2026-09-20 14:09:15', null, null),
    (1, 1651, 2, '1010201001', 1, 0, 1000, null, null, '0', 'OLM', '2026-09-20 14:09:15', null, null),
    (1, 1652, 1, '1010102001', 1, 3400, 0, null, null, '0', 'OLM', '2026-09-20 14:13:16', null, null),
    (1, 1652, 2, '1010201001', 1, 0, 3400, null, null, '0', 'OLM', '2026-09-20 14:13:16', null, null),
    (1, 1653, 1, '1010102002', 1, 22500, 0, null, null, '0', 'OLM', '2026-09-20 15:17:09', null, null),
    (1, 1653, 2, '1010201001', 1, 0, 22500, null, null, '0', 'OLM', '2026-09-20 15:17:09', null, null),
    (1, 1654, 1, '1010102001', 1, 6000, 0, null, null, '0', 'OLM', '2026-09-20 15:18:38', null, null),
    (1, 1654, 2, '1010201001', 1, 0, 6000, null, null, '0', 'OLM', '2026-09-20 15:18:38', null, null),
    (1, 1655, 1, '1010102002', 1, 850, 0, null, null, '0', 'OLM', '2026-09-20 15:19:37', null, null),
    (1, 1655, 2, '1010201001', 1, 0, 850, null, null, '0', 'OLM', '2026-09-20 15:19:37', null, null),
    (1, 1656, 1, '1010102002', 1, 2250, 0, null, null, '0', 'OLM', '2026-09-20 15:26:59', null, null),
    (1, 1656, 2, '1010201001', 1, 0, 2250, null, null, '0', 'OLM', '2026-09-20 15:26:59', null, null),
    (1, 1657, 1, '1010102002', 1, 22500, 0, null, null, '0', 'OLM', '2026-09-20 15:34:00', null, null),
    (1, 1657, 2, '1010201001', 1, 0, 22500, null, null, '0', 'OLM', '2026-09-20 15:34:00', null, null),
    (1, 1658, 1, '1010102002', 1, 3750, 0, null, null, '0', 'OLM', '2026-09-20 15:35:26', null, null),
    (1, 1658, 2, '1010201001', 1, 0, 3750, null, null, '0', 'OLM', '2026-09-20 15:35:26', null, null),
    (1, 1659, 1, '1010102002', 1, 700, 0, null, null, '0', 'OLM', '2026-10-12 16:22:46', null, null),
    (1, 1659, 2, '1010201001', 1, 0, 700, null, null, '0', 'OLM', '2026-10-12 16:22:46', null, null),
    (1, 1660, 1, '1010102001', 1, 2900, 0, null, null, '0', 'OLM', '2026-10-23 10:12:49', null, null),
    (1, 1660, 2, '1010201001', 1, 0, 2900, null, null, '0', 'OLM', '2026-10-23 10:12:49', null, null),
    (1, 1661, 1, '1010102001', 1, 850, 0, null, null, '0', 'OLM', '2026-10-23 10:21:10', null, null),
    (1, 1661, 2, '1010201001', 1, 0, 850, null, null, '0', 'OLM', '2026-10-23 10:21:10', null, null)) as x(loc, documento, linea, codigo, version, debe, haber, debe_mi, haber_mi, centro, usr_ing, f_ing, usr_mod, f_mod) loop
    select id into v_loc from public.localidades where organizacion_id = v_org and correlativo = r.loc;
    v_id := null;
    select id into v_id from public.movimientos_bancarios where localidad_id = v_loc and tipo = 'DEPOSITO' and deposito_anterior = r.documento;
    if v_id is null then l_s := l_s + 1; continue; end if;
    v_cta := null;
    select k.id into v_cta from public.cuentas k join public.catalogos_cuentas g on g.id = k.catalogo_id
    where g.localidad_id = v_loc and k.codigo = r.codigo order by (g.version = r.version) desc, g.activo desc, g.version desc limit 1;
    if v_cta is null then l_c := l_c + 1; v_faltan := array_append(v_faltan, format('3-0%s %s', r.loc, r.codigo)); continue; end if;
    insert into public.movimiento_lineas (movimiento_id, linea, cuenta_id, debe, haber, debe_mi, haber_mi, cuenta_codigo_anterior, version_cuenta_anterior,
      centro_costo_anterior, usuario_ingresa_anterior, fecha_ingresa_anterior, usuario_modifica_anterior, fecha_modifica_anterior)
    values (v_id, r.linea, v_cta, r.debe, r.haber, r.debe_mi::numeric, r.haber_mi::numeric, r.codigo, r.version, r.centro::text, r.usr_ing::text, r.f_ing::timestamp, r.usr_mod::text, r.f_mod::timestamp)
    on conflict (movimiento_id, linea) do update set cuenta_id = excluded.cuenta_id, debe = excluded.debe, haber = excluded.haber, debe_mi = excluded.debe_mi,
      haber_mi = excluded.haber_mi, cuenta_codigo_anterior = excluded.cuenta_codigo_anterior, version_cuenta_anterior = excluded.version_cuenta_anterior,
      centro_costo_anterior = excluded.centro_costo_anterior, usuario_ingresa_anterior = excluded.usuario_ingresa_anterior, fecha_ingresa_anterior = excluded.fecha_ingresa_anterior,
      usuario_modifica_anterior = excluded.usuario_modifica_anterior, fecha_modifica_anterior = excluded.fecha_modifica_anterior
    returning (xmax = 0) into v_nuevo;
    if v_nuevo then l_n := l_n + 1; else l_a := l_a + 1; end if;
  end loop;

  alter table public.movimientos_bancarios enable trigger movimientos_bancarios_preparar;
  alter table public.movimiento_lineas enable trigger movimiento_lineas_validar;

  raise notice '%', format('Depósitos: %s nuevos, %s actualizados, %s sin cuenta bancaria; %s recibos físicos. Detalle contable: %s líneas nuevas, %s actualizadas, %s sin depósito, %s sin cuenta.',
    c_n, c_a, c_s, d_n, l_n, l_a, l_s, l_c);
  if l_c > 0 then raise notice 'Cuentas que no existen en el catálogo de la localidad (líneas omitidas): %.', (select string_agg(distinct x, ', ') from unnest(v_faltan) x); end if;
end;
$migra$;

notify pgrst, 'reload schema';
